1	//! Lightweight discovery of bivvy config files.
2	//!
3	//! This module answers "what files exist?" and parses minimal headers.
4	//! It never performs deep merge or full schema parsing — those live in
5	//! [`crate::config::loader`]. Discovery is the cheap front end that lets
6	//! commands like `bivvy list` and `bivvy lint <name>` operate on a single
7	//! file without paying the merge tax.
8	
9	use std::fs;
10	use std::path::{Path, PathBuf};
11	
12	use crate::error::{BivvyError, Result};
13	
14	/// Lightweight discovery of bivvy config files for a project.
15	#[derive(Debug, Clone)]
16	pub struct Discovery {
17	    project_root: PathBuf,
18	}
19	
20	impl Discovery {
21	    /// Create a new discovery rooted at the given project directory.
22	    pub fn new(project_root: &Path) -> Self {
23	        Self {
24	            project_root: project_root.to_path_buf(),
25	        }
26	    }
27	
28	    /// Path to `.bivvy/config.yml` if it exists.
29	    pub fn project_config_path(&self) -> Option<PathBuf> {
30	        let path = self.project_root.join(".bivvy").join("config.yml");
31	        path.exists().then_some(path)
32	    }
33	
34	    /// Path to `.bivvy/config.local.yml` if it exists.
35	    pub fn local_config_path(&self) -> Option<PathBuf> {
36	        let path = self.project_root.join(".bivvy").join("config.local.yml");
37	        path.exists().then_some(path)
38	    }
39	
40	    /// All YAML files in `.bivvy/workflows/`, sorted.
41	    pub fn workflow_files(&self) -> Vec<PathBuf> {
42	        Self::yaml_files(&self.project_root.join(".bivvy").join("workflows"))
43	    }
44	
45	    /// All YAML files in `.bivvy/steps/`, sorted.
46	    pub fn step_files(&self) -> Vec<PathBuf> {
47	        Self::yaml_files(&self.project_root.join(".bivvy").join("steps"))
48	    }
49	
50	    /// Filename stems of every workflow file in `.bivvy/workflows/`, sorted.
51	    pub fn workflow_names(&self) -> Vec<String> {
52	        Self::file_stems(&self.workflow_files())
53	    }
54	
55	    /// Filename stems of every step file in `.bivvy/steps/`, sorted.
56	    pub fn step_file_names(&self) -> Vec<String> {
57	        Self::file_stems(&self.step_files())
58	    }
59	
60	    /// Return the path to `.bivvy/workflows/<name>.yml` if it exists.
61	    pub fn workflow_path(&self, name: &str) -> Option<PathBuf> {
62	        let primary = self
63	            .project_root
64	            .join(".bivvy")
65	            .join("workflows")
66	            .join(format!("{name}.yml"));
67	        if primary.exists() {
68	            return Some(primary);
69	        }
70	        let alt = self
71	            .project_root
72	            .join(".bivvy")
73	            .join("workflows")
74	            .join(format!("{name}.yaml"));
75	        alt.exists().then_some(alt)
76	    }
77	
78	    /// Return the path to `.bivvy/steps/<name>.yml` if it exists.
79	    pub fn step_path(&self, name: &str) -> Option<PathBuf> {
80	        let primary = self
81	            .project_root
82	            .join(".bivvy")
83	            .join("steps")
84	            .join(format!("{name}.yml"));
85	        if primary.exists() {
86	            return Some(primary);
87	        }
88	        let alt = self
89	            .project_root
90	            .join(".bivvy")
91	            .join("steps")
92	            .join(format!("{name}.yaml"));
93	        alt.exists().then_some(alt)
94	    }
95	
96	    /// Light parse: extracts the description and step list from a workflow
97	    /// file without deserializing the full schema. Works with both new
98	    /// (`WorkflowFile`) and legacy (`WorkflowConfig`) shapes.
99	    pub fn workflow_header(&self, name: &str) -> Result<WorkflowHeader> {
100	        let path = self
101	            .workflow_path(name)
102	            .ok_or_else(|| BivvyError::ConfigNotFound {
103	                path: self
104	                    .project_root
105	                    .join(".bivvy")
106	                    .join("workflows")
107	                    .join(format!("{name}.yml")),
108	            })?;
109	        let content = fs::read_to_string(&path).map_err(BivvyError::Io)?;
110	        let value: serde_yaml::Value =
111	            serde_yaml::from_str(&content).map_err(|e| BivvyError::ConfigParseError {
112	                path: path.clone(),
113	                message: e.to_string(),
114	            })?;
115	
116	        let description = value
117	            .get("description")
118	            .and_then(|v| v.as_str())
119	            .map(|s| s.to_string());
120	
121	        // New format: workflow.steps. Legacy format: top-level steps.
122	        let step_names = if let Some(seq) = value
123	            .get("workflow")
124	            .and_then(|w| w.get("steps"))
125	            .and_then(|s| s.as_sequence())
126	        {
127	            seq.iter()
128	                .filter_map(|v| v.as_str().map(|s| s.to_string()))
129	                .collect()
130	        } else if let Some(seq) = value.get("steps").and_then(|s| s.as_sequence()) {
131	            seq.iter()
132	                .filter_map(|v| v.as_str().map(|s| s.to_string()))
133	                .collect()
134	        } else {
135	            Vec::new()
136	        };
137	
138	        Ok(WorkflowHeader {
139	            name: name.to_string(),
140	            description,
141	            step_names,
142	        })
143	    }
144	
145	    fn yaml_files(dir: &Path) -> Vec<PathBuf> {
146	        if !dir.is_dir() {
147	            return Vec::new();
148	        }
149	        let mut files: Vec<PathBuf> = fs::read_dir(dir)
150	            .into_iter()
151	            .flatten()
152	            .filter_map(|entry| entry.ok())
153	            .map(|entry| entry.path())
154	            .filter(|path| {
155	                path.extension()
156	                    .is_some_and(|ext| ext == "yml" || ext == "yaml")
157	            })
158	            .collect();
159	        files.sort();
160	        files
161	    }
162	
163	    fn file_stems(paths: &[PathBuf]) -> Vec<String> {
164	        paths
165	            .iter()
166	            .filter_map(|p| {
167	                p.file_stem()
168	                    .and_then(|s| s.to_str())
169	                    .map(|s| s.to_string())
170	            })
171	            .collect()
172	    }
173	}
174	
175	/// Lightweight header info for a workflow file.
176	#[derive(Debug, Clone)]
177	pub struct WorkflowHeader {
178	    /// Workflow name (filename stem).
179	    pub name: String,
180	
181	    /// Human-readable description (`description:` in either format).
182	    pub description: Option<String>,
183	
184	    /// Step names referenced by the workflow's ordering list.
185	    pub step_names: Vec<String>,
186	}
187	
188	#[cfg(test)]
189	mod tests {
190	    use super::*;
191	    use tempfile::TempDir;
192	
193	    fn setup(workflows: &[(&str, &str)], steps: &[(&str, &str)]) -> TempDir {
194	        let temp = TempDir::new().unwrap();
195	        let bivvy = temp.path().join(".bivvy");
196	        fs::create_dir_all(&bivvy).unwrap();
197	        if !workflows.is_empty() {
198	            let dir = bivvy.join("workflows");
199	            fs::create_dir_all(&dir).unwrap();
200	            for (name, content) in workflows {
201	                fs::write(dir.join(format!("{name}.yml")), content).unwrap();
202	            }
203	        }
204	        if !steps.is_empty() {
205	            let dir = bivvy.join("steps");
206	            fs::create_dir_all(&dir).unwrap();
207	            for (name, content) in steps {
208	                fs::write(dir.join(format!("{name}.yml")), content).unwrap();
209	            }
210	        }
211	        temp
212	    }
213	
214	    #[test]
215	    fn workflow_files_are_sorted() {
