237	
238	        let d = Discovery::new(temp.path());
239	        assert_eq!(d.workflow_names(), vec!["ok"]);
240	    }
241	
242	    #[test]
243	    fn workflow_header_parses_legacy_format() {
244	        let temp = setup(
245	            &[(
246	                "ci",
247	                r#"
248	description: CI pipeline
249	steps:
250	  - install
251	  - test
252	"#,
253	            )],
254	            &[],
255	        );
256	        let d = Discovery::new(temp.path());
