1	//! Config command implementation.
2	//!
3	//! The `bivvy config` command shows resolved configuration.
4	
5	use std::path::{Path, PathBuf};
6	
7	use crate::cli::args::ConfigArgs;
8	use crate::config::{load_config_file, load_merged_config, ConfigPaths};
9	use crate::error::{BivvyError, Result};
10	use crate::ui::{OutputMode, UserInterface};
11	
12	use super::dispatcher::{Command, CommandResult};
13	
14	/// The config command implementation.
15	pub struct ConfigCommand {
16	    project_root: PathBuf,
17	    args: ConfigArgs,
18	    config_override: Option<PathBuf>,
19	}
20	
21	impl ConfigCommand {
22	    /// Create a new config command.
23	    pub fn new(project_root: &Path, args: ConfigArgs) -> Self {
24	        Self {
25	            project_root: project_root.to_path_buf(),
26	            args,
27	            config_override: None,
28	        }
29	    }
30	
31	    /// Set an override config path.
32	    pub fn with_config_override(mut self, config_override: Option<PathBuf>) -> Self {
33	        self.config_override = config_override;
34	        self
35	    }
36	
37	    /// Get the project root path.
38	    pub fn project_root(&self) -> &Path {
39	        &self.project_root
40	    }
41	
42	    /// Get the command arguments.
43	    pub fn args(&self) -> &ConfigArgs {
44	        &self.args
45	    }
46	}
47	
48	impl Command for ConfigCommand {
49	    fn execute(&self, ui: &mut dyn UserInterface) -> Result<CommandResult> {
50	        let paths = ConfigPaths::discover(&self.project_root);
51	
52	        // Load configuration: override path, merged (all sources), or project-only
53	        let config = if let Some(ref override_path) = self.config_override {
54	            load_config_file(override_path)?
55	        } else if self.args.merged {
56	            match load_merged_config(&self.project_root) {
57	                Ok(c) => c,
58	                Err(BivvyError::ConfigNotFound { .. }) => {
59	                    ui.error("No configuration found. Run 'bivvy init' first.");
60	                    return Ok(CommandResult::failure(2));
61	                }
62	                Err(e) => return Err(e),
63	            }
64	        } else {
65	            // Load only the project config (.bivvy/config.yml) without merging
66	            match &paths.project {
67	                Some(project_path) => load_config_file(project_path)?,
68	                None => {
69	                    ui.error("No configuration found. Run 'bivvy init' first.");
70	                    return Ok(CommandResult::failure(2));
71	                }
72	            }
73	        };
74	
75	        // Apply config default_output when no CLI flag was explicitly set
76	        if ui.output_mode() == OutputMode::Normal {
77	            ui.set_output_mode(config.settings.defaults.output.into());
78	        }
79	
80	        // Show config file path(s)
81	        if self.args.merged {
82	            let existing: Vec<_> = paths.all_existing();
83	            if !existing.is_empty() {
84	                for path in &existing {
85	                    ui.message(&format!("# {}", path.display()));
86	                }
87	                ui.message("");
88	            }
89	        } else if let Some(project_path) = &paths.project {
90	            ui.message(&format!("# {}", project_path.display()));
91	            ui.message("");
92	        }
93	
94	        // Output format
95	        if self.args.json {
96	            let json =
97	                serde_json::to_string_pretty(&config).map_err(|e| BivvyError::Other(e.into()))?;
98	            ui.message(&json);
99	        } else {
100	            // --yaml or default: output as YAML
101	            let yaml = serde_yaml::to_string(&config).map_err(|e| BivvyError::Other(e.into()))?;
102	            ui.message(&yaml);
103	        }
104	
105	        Ok(CommandResult::success())
106	    }
107	}
108	
109	#[cfg(test)]
110	mod tests {
111	    use super::*;
112	    use crate::ui::{MockUI, UiState};
113	    use std::fs;
114	    use tempfile::TempDir;
115	
116	    fn setup_project(config: &str) -> TempDir {
117	        let temp = TempDir::new().unwrap();
118	        let bivvy_dir = temp.path().join(".bivvy");
119	        fs::create_dir_all(&bivvy_dir).unwrap();
120	        fs::write(bivvy_dir.join("config.yml"), config).unwrap();
121	        temp
122	    }
123	
124	    #[test]
125	    fn config_command_creation() {
126	        let temp = TempDir::new().unwrap();
127	        let args = ConfigArgs::default();
128	        let cmd = ConfigCommand::new(temp.path(), args);
129	
130	        assert_eq!(cmd.project_root(), temp.path());
131	    }
132	
133	    #[test]
134	    fn config_no_config() {
135	        let temp = TempDir::new().unwrap();
136	        let args = ConfigArgs::default();
137	        let cmd = ConfigCommand::new(temp.path(), args);
138	        let mut ui = MockUI::new();
139	
140	        let result = cmd.execute(&mut ui).unwrap();
141	
142	        assert!(!result.success);
143	        assert_eq!(result.exit_code, 2);
144	    }
145	
146	    #[test]
147	    fn config_shows_config_path() {
148	        let config = r#"
149	app_name: Test
150	steps:
151	  hello:
152	    command: echo hello
153	workflows:
154	  default:
155	    steps: [hello]
156	"#;
157	        let temp = setup_project(config);
158	        let args = ConfigArgs::default();
159	        let cmd = ConfigCommand::new(temp.path(), args);
160	        let mut ui = MockUI::new();
161	
162	        cmd.execute(&mut ui).unwrap();
163	
164	        assert!(ui.messages().iter().any(|m| m.contains("config.yml")));
165	    }
166	
167	    #[test]
168	    fn config_applies_config_default_output() {
169	        let config = r#"
170	app_name: Test
171	settings:
172	  defaults:
173	    output: quiet
174	steps:
175	  hello:
176	    command: echo hello
177	workflows:
178	  default:
179	    steps: [hello]
180	"#;
181	        let temp = setup_project(config);
182	        let args = ConfigArgs::default();
183	        let cmd = ConfigCommand::new(temp.path(), args);
184	        let mut ui = MockUI::new();
185	
186	        cmd.execute(&mut ui).unwrap();
187	
188	        assert_eq!(ui.output_mode(), crate::ui::OutputMode::Quiet);
189	    }
190	
191	    #[test]
192	    fn config_yaml_output() {
193	        let config = r#"
194	app_name: Test
195	steps:
196	  hello:
197	    command: echo hello
198	workflows:
199	  default:
200	    steps: [hello]
201	"#;
202	        let temp = setup_project(config);
203	        let args = ConfigArgs::default();
204	        let cmd = ConfigCommand::new(temp.path(), args);
205	        let mut ui = MockUI::new();
206	
207	        let result = cmd.execute(&mut ui).unwrap();
208	
209	        assert!(result.success);
210	    }
211	
212	    #[test]
213	    fn config_json_output() {
214	        let config = r#"
215	app_name: Test
216	steps:
217	  hello:
218	    command: echo hello
219	workflows:
220	  default:
221	    steps: [hello]
222	"#;
223	        let temp = setup_project(config);
224	        let args = ConfigArgs {
225	            json: true,
226	            ..Default::default()
